<script lang="ts">
 import { onMount } from 'svelte';import { drafts,saveDraft,type Draft } from '$lib/offline';import { translator } from '$lib/app-i18n';import type { Language } from '$lib/i18n';
 let lang=$state<Language>('de'),tenantId=$state(''),items=$state<Draft[]>([]),body=$state(''),title=$state(''),message=$state('');let t=$derived(translator(lang));
 onMount(()=>{tenantId=localStorage.getItem('vinea-active-winery')??'';lang=(localStorage.getItem('vinea-language')??'de') as Language;if(tenantId)drafts(tenantId).then(rows=>items=rows);});
 async function save(type:string){await saveDraft(tenantId,type==='note_add'?{type,body,captured_at:new Date().toISOString()}:{type,title});items=await drafts(tenantId);body='';title='';message=t('draftSaved');}
</script>
<main><h1>Vinea · {t('draft')}</h1><p>{t('offline')}</p>{#if tenantId}<form onsubmit={(e)=>{e.preventDefault();save('note_add');}}><label>{t('body')}<textarea bind:value={body} required maxlength="5000"></textarea></label><button>{t('note_add')}</button></form><form onsubmit={(e)=>{e.preventDefault();save('task_create');}}><label>{t('title')}<input bind:value={title} required maxlength="160" /></label><button>{t('task_create')}</button></form><p role="status">{message}</p><ul>{#each items as item}<li>{t(String(item.command.type))} · {item.capturedAt}</li>{/each}</ul>{/if}<a href="/app/today">{t('sync')}</a></main>
<style>:global(body){font-family:system-ui;background:#f7f7f3;color:#263b32}main{max-width:640px;margin:60px auto;padding:25px}h1{font:36px Georgia}form{margin:30px 0;display:grid;gap:14px}label{display:grid;gap:8px}input,textarea{padding:12px;border:1px solid #d9dfd5;border-radius:7px;font:inherit}button{padding:12px;background:#285741;color:white;border:0;border-radius:7px}</style>
